import{_ as a,o as i,c as t,aj as s}from"./chunks/framework.C6uXqnaX.js";const k=JSON.parse('{"title":"Property Binding in Angular","description":"","frontmatter":{},"headers":[],"relativePath":"en/tutorials/learn-angular/6-property-binding.md","filePath":"en/tutorials/learn-angular/6-property-binding.md"}'),n={name:"en/tutorials/learn-angular/6-property-binding.md"};function l(p,e,o,d,r,h){return i(),t("div",null,e[0]||(e[0]=[s('<h1 id="property-binding-in-angular" tabindex="-1">Property Binding in Angular <a class="header-anchor" href="#property-binding-in-angular" aria-label="Permalink to &quot;Property Binding in Angular&quot;">​</a></h1><p>Property binding in Angular enables you to set values for properties of HTML elements, Angular components and more.</p><p>Use property binding to dynamically set values for properties and attributes. You can do things such as toggle button features, set image paths programmatically, and share values between components.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Learn more about <a href="/en/essentials/templates#setting-dynamic-properties-and-attributes">setting dynamic properties and attributes in the essentials guide</a>.</p></div><p>In this activity, you&#39;ll learn how to use property binding in templates.</p><hr><p>To bind to an element&#39;s attribute, wrap the attribute name in square brackets. Here&#39;s an example:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> alt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;photo&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> [src]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;imageURL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>In this example, the value of the <code>src</code> attribute will be bound to the class property <code>imageURL</code>. Whatever value <code>imageURL</code> has will be set as the <code>src</code> attribute of the <code>img</code> tag.</p><h3 id="_1-add-a-property-called-iseditable" tabindex="-1">1. Add a property called <code>isEditable</code> <a class="header-anchor" href="#_1-add-a-property-called-iseditable" aria-label="Permalink to &quot;1. Add a property called `isEditable`&quot;">​</a></h3><p>Update the code in <code>app.ts</code> by adding a property to the <code>App</code> class called <code>isEditable</code> with the initial value set to <code>true</code>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> App</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  isEditable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="_2-bind-to-contenteditable" tabindex="-1">2. Bind to <code>contentEditable</code> <a class="header-anchor" href="#_2-bind-to-contenteditable" aria-label="Permalink to &quot;2. Bind to `contentEditable`&quot;">​</a></h3><p>Next, bind the <code>contentEditable</code> attribute of the <code>div</code> to the <code>isEditable</code> property by using the <code aria-label="square brackets">[]</code> syntax.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Component</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ...</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  template: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`&lt;div [contentEditable]=&quot;isEditable&quot;&gt;&lt;/div&gt;`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>The div is now editable. Nice work 👍</p><p>Property binding is one of Angular&#39;s many powerful features. If you&#39;d like to learn more checkout <a href="/en/guide/templates/binding#css-class-and-style-property-bindings">the Angular documentation</a>.</p>',17)]))}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
